class Alarm(object):
    def __init__(self, alarm_number=None, alarm_name=None, alarm_severity=None,
                 alarming_resource_dist_name=None, alarm_detail=None, fault_name=None, fault_id=None,
                 fault_severity=None):
        """
        :param int alarm_number: alarm id
        :param str alarm_name: alarm name
        :param str alarm_severity: alarm severity
        :param str alarming_resource_dist_name: alarm resource DN
        :param str alarm_detail: alarm - mostly  the same like fault description
        :param str fault_name: fault name
        :param int fault_id: fault id
        :param str fault_severity: fault severuty
        """
        self.__attr_names = []
        self._alarm_set_timestamp = None
        self._alarm_removed_timestamp = None
        for param_name, param_value in locals().items():
            if param_name != 'self':
                setattr(self, param_name, param_value)
                self.__attr_names.append(param_name)

    @property
    def alarm_set_timestamp(self):
        """
        Get alarm_set_timestamp
        :return: alarm_set_timestamp
        """
        return self._alarm_set_timestamp

    @alarm_set_timestamp.setter
    def alarm_set_timestamp(self, timestamp):
        """
        Set alarm_set_timestamp
        :param timestamp: datetime object
        """
        self._alarm_set_timestamp = timestamp

    @property
    def alarm_removed_timestamp(self):
        """
        Get alarm_removed_timestamp
        :return: alarm_set_timestamp
        """
        return self._alarm_removed_timestamp

    @alarm_removed_timestamp.setter
    def alarm_removed_timestamp(self, timestamp):
        """
        Set alarm_removed_timestamp
        :param timestamp: datetime object
        """
        self._alarm_removed_timestamp = timestamp

    def to_dict(self):
        """
        Return representative of Alarm object to dict
        :return: alarm_dict
        """
        alarm_dict = {}
        for param_name in self.__attr_names:
            alarm_dict[param_name] = getattr(self, param_name)
        alarm_dict['alarm_set_timestamp'] = self.alarm_set_timestamp
        alarm_dict['alarm_removed_timestamp'] = self.alarm_removed_timestamp
        return alarm_dict

    def to_simplified_dict(self):
        """
        Return representative of Alarm object to simplified dict. contains only basic information like:
        'fault_name', 'fault_id', 'alarm_set_timestamp', 'alarm_removed_timestamp'
        :return: simplified_dict
        """
        required_params = ['fault_name', 'fault_id', 'alarm_set_timestamp', 'alarm_removed_timestamp']
        simplified_dict = {}
        alarm_dict = self.to_dict()
        for param_name, param_value in alarm_dict.items():
            if param_value and param_name in required_params:
                simplified_dict[param_name] = param_value

        return simplified_dict

    def __repr__(self):
        return "Alarm({})".format(sorted(self.to_dict().items(), key=lambda x: x[0]))

    def __eq__(self, other):
        if not isinstance(other, self.__class__):
            return False

        partial_equalities = self.__get_partial_equalities(other)

        if not partial_equalities:
            return False

        return all(partial_equalities)

    def __ne__(self, other):
        return not self.__eq__(other)

    def __get_partial_equalities(self, other):
        partial_equalities = []
        for param_name in self.__attr_names:
            if getattr(self, param_name) is not None and getattr(other, param_name) is not None:
                partial_equalities.append(getattr(self, param_name) == getattr(other, param_name))

        return partial_equalities
